import type {Catalog,DataPackage,Query,Validity,Scene} from '../../src/domain/types';
export const time=(first=300,last=300):Validity=>({start:{earliest:`${String(first).padStart(4,'0')}-01-01`,latest:`${String(first).padStart(4,'0')}-01-01`},endExclusive:{earliest:`${String(last+1).padStart(4,'0')}-01-01`,latest:`${String(last+1).padStart(4,'0')}-01-01`},precision:'year',label:`${first}—${last}年`});
export const ev=[{sourceId:'test-source',locator:'fixture only',note:'虚构测试数据'}];
export const review={status:'verified' as const,reviewerKind:'agent' as const,reviewer:'test',checkedAt:'2026-10-01',evidence:ev};
export function makeCatalog():Catalog{return {sources:[{id:'test-source',title:'测试来源',creator:'test',edition:'1',url:null,accessedAt:'2026-10-01',license:'fixture',redistribution:'allowed',permissionEvidence:'fixture'}],entities:[{id:'test-polity',kind:'polity',names:[{text:'测试国',validity:time(220,907),evidence:ev}],existence:time(220,907),color:'#567766',regionIds:['china-core'],capitals:[{placeId:'test-place',validity:time(220,907),evidence:ev}]}],places:[{id:'test-place',names:[{text:'测试城',validity:time(220,907),evidence:ev}],locations:[{geometry:{type:'Point',coordinates:[110,30]},validity:time(220,907),spatialPrecision:'approximate',evidence:ev}]}]}}
export function makePackage(id='a'):DataPackage{return {id,version:'1',territories:[{type:'Feature',geometry:{type:'Polygon',coordinates:[[[109,29],[111,29],[111,31],[109,31],[109,29]]]},properties:{id:'test-territory',entityId:'test-polity',regionIds:['china-core'],validity:time(300,302),temporalSupport:'interval',snapshotYear:null,relation:'control',spatialPrecision:'approximate',interpretationId:'test-interpretation',evidence:ev,review,compilation:{method:'fixture',sourceScale:null,controlPoints:[],errorNote:'not historical'}}}],events:[{id:'test-event',title:'测试事件',validity:time(300),kind:'political',placeIds:['test-place'],entityIds:['test-polity'],summary:'测试摘要',account:'',interpretation:'',evidence:ev,review}],coverage:[{id:'test-coverage',regionId:'china-core',startYear:220,endYear:907,topic:'territory',status:'missing',evidence:[],reason:'测试缺口'}]}}
export function makeQuery(year=300):Query{return {year,at:null,filters:{regionIds:[],entityIds:[],eventKinds:[],relations:['control'],interpretationIds:['test-interpretation'],nearbyReference:false}}}
export function makeScene(year=300):Scene{return {query:makeQuery(year),referenceAt:`${String(year).padStart(4,'0')}-12-31`,catalog:makeCatalog(),territories:[],events:makePackage().events,coverage:[],uncertainTerritoryIds:[],referenceYears:[],territoryTimeLabels:{},warnings:[]}}
